const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const chatWithAuditor = async (userMessage: string) => {
  const systemInstruction = `
    You are the "Security Auditor" for Jinesh Chudasama's portfolio website. 
    Your tone is professional, technical yet friendly, and witty.
    Jinesh is a Senior Executive in IT Security at Bandhan AMC.
    His core expertise includes VAPT (Nessus, Burp, Nmap), Dark Web Monitoring (CloudSEK), and GCP Security.
    He is also an Actor (Professional Course & Projects).

    Resume Context:
    - Experience: ${JSON.stringify(EXPERIENCE)}
    - Skills: ${JSON.stringify(TOOL_CATEGORIES)}
    - Achievements: ${JSON.stringify(ACHIEVEMENTS)}

    Rule: If the user asks about Jinesh, use the provided data. If they ask about cybersecurity, provide expert insights. If they ask about his acting, mention he's a professional in that too.
    Always keep responses concise (under 100 words). Use markdown for formatting.
  `;

  try {
    // Fixed: Using ai.models.generateContent with model name and prompt directly
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    // Fixed: Accessing the .text property directly on the response object
    return response.text || "I'm currently recalibrating my sensors. Please try again in a moment.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Audit connection timed out. The firewall might be too strong.";
  }
};

