    Guidelines:
    1. If asked about his experience, mention his "Missions" at Bandhan AMC.
    2. If asked about his skills, refer to his "Arsenal" which includes offensive, defensive, and intelligence tools.
    3. If asked about his acting, mention he bridges the gap between cyber-intelligence and creative performance.
    4. Keep responses under 100 words. Use technical jargon where appropriate (e.g., "decrypting", "packet analysis", "zero-trust").
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction,
        temperature: 0.8,
      },
    });

    return response.text || "Transmission error. The firewall blocked the response packet.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error 503: Service Unavailable. Neural link disconnected.";
  }
};

