import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Terminal as TerminalIcon, Send, ShieldAlert, X } from 'lucide-react';
import { chatWithAuditor } from '../services/geminiService';

const SecurityTerminal: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [history, setHistory] = useState<{ type: 'user' | 'bot'; text: string }[]>([
    { type: 'bot', text: "Access Granted. I am the Security Auditor. How can I assist you with Jinesh's profile today?" }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Futuristic Sound Engine
  const playSound = (type: 'open' | 'close' | 'send' | 'receive') => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      const now = ctx.currentTime;

      switch (type) {
        case 'open':
          osc.type = 'sine';
          osc.frequency.setValueAtTime(400, now);
          osc.frequency.exponentialRampToValueAtTime(1200, now + 0.15);
          gain.gain.setValueAtTime(0, now);
          gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
          osc.start(now);
          osc.stop(now + 0.15);
          break;
        case 'close':
          osc.type = 'sine';
          osc.frequency.setValueAtTime(1200, now);
          osc.frequency.exponentialRampToValueAtTime(300, now + 0.2);
          gain.gain.setValueAtTime(0.1, now);
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
          osc.start(now);
          osc.stop(now + 0.2);
          break;
        case 'send':
          osc.type = 'square';
          osc.frequency.setValueAtTime(1500, now);
          osc.frequency.exponentialRampToValueAtTime(1000, now + 0.05);
          gain.gain.setValueAtTime(0.05, now);
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
          osc.start(now);
          osc.stop(now + 0.05);
          break;
        case 'receive':
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(800, now);
          osc.frequency.setValueAtTime(1000, now + 0.08);
          gain.gain.setValueAtTime(0.08, now);
          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
          osc.start(now);
          osc.stop(now + 0.2);
          break;
      }
    } catch (e) {
      console.warn("Audio Context failed to initialize", e);
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history, isTyping]);

  const toggleTerminal = (state: boolean) => {
    setIsOpen(state);
    playSound(state ? 'open' : 'close');
  };

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg = input;
    setHistory(prev => [...prev, { type: 'user', text: userMsg }]);
    setInput('');
    setIsTyping(true);
    playSound('send');

    const botMsg = await chatWithAuditor(userMsg);
    setHistory(prev => [...prev, { type: 'bot', text: botMsg }]);
    setIsTyping(false);
    playSound('receive');
  };

  return (
    <>
      {/* Floating Toggle */}
      <motion.button
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => toggleTerminal(true)}
        className="fixed bottom-8 right-8 z-50 p-4 bg-emerald-600 text-white rounded-full shadow-lg shadow-emerald-900/40 border border-emerald-400/30 flex items-center justify-center"
      >
        <TerminalIcon size={24} />
      </motion.button>

      {/* Terminal Window */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 100, scale: 0.9 }}
            className="fixed bottom-24 right-8 z-50 w-full max-w-md bg-zinc-950 border border-zinc-800 rounded-xl shadow-2xl overflow-hidden flex flex-col h-[500px]"
          >
            {/* Header */}
            <div className="bg-zinc-900 px-4 py-3 flex items-center justify-between border-b border-zinc-800">
              <div className="flex items-center gap-2 text-emerald-400">
                <ShieldAlert size={18} />
                <span className="text-sm font-bold uppercase tracking-widest mono">Security Audit v1.0</span>
              </div>
              <button onClick={() => toggleTerminal(false)} className="text-zinc-500 hover:text-white p-1">
                <X size={18} />
              </button>
            </div>

            {/* Content */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 mono text-sm scroll-smooth bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.03)_0%,transparent_100%)]">
              {history.map((msg, i) => (
                <div key={i} className={`flex ${msg.type === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-3 rounded-lg ${msg.type === 'user' ? 'bg-zinc-800 text-zinc-100' : 'bg-emerald-950/30 border border-emerald-900/50 text-emerald-400'}`}>
                    <span className="opacity-50 text-[10px] block mb-1 uppercase tracking-tighter">
                      {msg.type === 'user' ? 'Guest' : 'Auditor'}
                    </span>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-emerald-950/30 p-3 rounded-lg text-emerald-400 animate-pulse">
                    Decrypting incoming packet...
                  </div>
                </div>
              )}
            </div>

            {/* Input */}
