const Cursor: React.FC = () => {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [isPointer, setIsPointer] = useState(false);

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      const target = e.target as HTMLElement;
      setIsPointer(window.getComputedStyle(target).cursor === 'pointer' || target.closest('a') !== null || target.closest('button') !== null);
    };
    window.addEventListener('mousemove', handleMove);
    return () => window.removeEventListener('mousemove', handleMove);
  }, []);

  return (
    <>
      <motion.div
        className="fixed top-0 left-0 w-10 h-10 border-2 border-[#00ff41] z-[99999] pointer-events-none mix-blend-screen"
        animate={{ 
          x: position.x - 20, 
          y: position.y - 20, 
          scale: isPointer ? 1.4 : 1, 
          rotate: isPointer ? 90 : 0,
          borderRadius: isPointer ? "2px" : "50%"
        }}
        transition={{ type: 'spring', damping: 25, stiffness: 250, mass: 0.4 }}
      >
        <div className="absolute top-0 left-0 w-full h-full border border-[#ff003c] scale-125 opacity-20" />
      </motion.div>
      <motion.div
        className="fixed top-0 left-0 w-2 h-2 bg-[#00ff41] z-[99999] pointer-events-none rounded-full"
        animate={{ x: position.x - 4, y: position.y - 4 }}
        transition={{ type: 'spring', damping: 40, stiffness: 600, mass: 0.1 }}
      />
    </>
  );
};

const GlitchText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  const [displayText, setDisplayText] = useState(text);
  const chars = "X01!@#$%&*+=-_";

  const trigger = () => {
    let iterations = 0;
    const interval = setInterval(() => {
      setDisplayText(prev => 
        prev.split("").map((c, i) => {
          if (i < iterations) return text[i];
          return chars[Math.floor(Math.random() * chars.length)];
        }).join("")
      );
      if (iterations >= text.length) clearInterval(interval);
      iterations += 1/3;
    }, 25);
  };

  useEffect(() => { trigger(); }, [text]);

  return <span className={className} onMouseEnter={trigger}>{displayText}</span>;
};

