const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const droneOscRef = useRef<OscillatorNode | null>(null);
  const pulseOscRef = useRef<OscillatorNode | null>(null);
  const gainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  // Dark Series Background Soundtrack Synthesis
  useEffect(() => {
    if (hasEntered) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioContextRef.current = ctx;

      // Deep Drone (Bass)
      const droneOsc = ctx.createOscillator();
      const droneFilter = ctx.createBiquadFilter();
      const droneGain = ctx.createGain();

      droneOsc.type = 'sawtooth';
      droneOsc.frequency.setValueAtTime(32.70, ctx.currentTime); // C1 - Deep
      droneFilter.type = 'lowpass';
      droneFilter.frequency.setValueAtTime(150, ctx.currentTime);
      droneGain.gain.setValueAtTime(0, ctx.currentTime);

      droneOsc.connect(droneFilter);
      droneFilter.connect(droneGain);
      droneGain.connect(ctx.destination);
      droneOsc.start();

      // Secondary Pulse (Rhythm)
      const pulseOsc = ctx.createOscillator();
      const pulseGain = ctx.createGain();
      pulseOsc.type = 'triangle';
      pulseOsc.frequency.setValueAtTime(41.20, ctx.currentTime); // E1
      pulseGain.gain.setValueAtTime(0, ctx.currentTime);

      pulseOsc.connect(pulseGain);
      pulseGain.connect(ctx.destination);
      pulseOsc.start();

      // Breathing LFO
      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.setValueAtTime(0.15, ctx.currentTime);
      lfoGain.gain.setValueAtTime(80, ctx.currentTime);
      lfo.connect(lfoGain);
      lfoGain.connect(droneFilter.frequency);
      lfo.start();

      droneOscRef.current = droneOsc;
      pulseOscRef.current = pulseOsc;
      gainRef.current = droneGain;

      // Unmute sequence
      if (!isMuted) {
        droneGain.gain.linearRampToValueAtTime(0.12, ctx.currentTime + 4);
        pulseGain.gain.linearRampToValueAtTime(0.04, ctx.currentTime + 4);
      }
    }

    return () => {
      if (audioContextRef.current) audioContextRef.current.close();
    };
  }, [hasEntered]);

  useEffect(() => {
    if (gainRef.current && audioContextRef.current) {
      const target = isMuted ? 0.001 : 0.12;
