const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  // Immersive Soundtrack Synthesis (Dark / Ben Frost style)
  useEffect(() => {
    if (hasEntered) {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // Layer 1: Sub-Harmonic Drone
      const drone = ctx.createOscillator();
      const droneFilter = ctx.createBiquadFilter();
      const droneGain = ctx.createGain();
      drone.type = 'sawtooth';
      drone.frequency.setValueAtTime(32.70, ctx.currentTime); // C1
      droneFilter.type = 'lowpass';
      droneFilter.frequency.setValueAtTime(80, ctx.currentTime);
      droneGain.gain.setValueAtTime(0.4, ctx.currentTime);
      drone.connect(droneFilter);
      droneFilter.connect(droneGain);
      droneGain.connect(masterGain);
      drone.start();

      // Layer 2: Ominous Pulse
      const pulse = ctx.createOscillator();
      const pulseGain = ctx.createGain();
      pulse.type = 'triangle';
      pulse.frequency.setValueAtTime(41.20, ctx.currentTime); // E1
      pulseGain.gain.setValueAtTime(0.15, ctx.currentTime);
      pulse.connect(pulseGain);
      pulseGain.connect(masterGain);
      pulse.start();

      // Layer 3: High-Freq Atmospheric Noise
      const bufferSize = 2 * ctx.sampleRate;
      const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const output = noiseBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        output[i] = Math.random() * 2 - 1;
      }
      const noise = ctx.createBufferSource();
      noise.buffer = noiseBuffer;
      noise.loop = true;
      const noiseFilter = ctx.createBiquadFilter();
      const noiseGain = ctx.createGain();
      noiseFilter.type = 'bandpass';
      noiseFilter.frequency.setValueAtTime(8000, ctx.currentTime);
      noiseFilter.Q.setValueAtTime(20, ctx.currentTime);
      noiseGain.gain.setValueAtTime(0.05, ctx.currentTime);
      noise.connect(noiseFilter);
      noiseFilter.connect(noiseGain);
      noiseGain.connect(masterGain);
      noise.start();

      // Volume Modulation (Breathing Effect)
      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.setValueAtTime(0.08, ctx.currentTime); // Very slow breath
      lfoGain.gain.setValueAtTime(0.05, ctx.currentTime);
      lfo.connect(lfoGain);
      lfoGain.connect(masterGain.gain);
      lfo.start();

      if (!isMuted) {
        masterGain.gain.linearRampToValueAtTime(0.35, ctx.currentTime + 5); // Louder default
      }
    }

    return () => {
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, [hasEntered]);

