const Cursor: React.FC = () => {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [isPointer, setIsPointer] = useState(false);

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      const target = e.target as HTMLElement;
      setIsPointer(
        window.getComputedStyle(target).cursor === 'pointer' || 
        target.closest('a') !== null || 
        target.closest('button') !== null
      );
    };
    window.addEventListener('mousemove', handleMove);
    return () => window.removeEventListener('mousemove', handleMove);
  }, []);

  return (
    <>
      <motion.div
        className="fixed top-0 left-0 w-12 h-12 border border-[#00ff41] z-[999999] pointer-events-none mix-blend-screen"
        animate={{ 
          x: position.x - 24, 
          y: position.y - 24, 
          scale: isPointer ? 1.5 : 1, 
          rotate: isPointer ? 90 : 0,
          borderRadius: isPointer ? "2px" : "50%",
          borderColor: isPointer ? "#ff003c" : "#00ff41"
        }}
        transition={{ type: 'spring', damping: 25, stiffness: 300, mass: 0.5 }}
      >
        <div className="absolute inset-0 border border-white opacity-10 scale-125" />
      </motion.div>
      <motion.div
        className="fixed top-0 left-0 w-1 h-1 bg-white z-[999999] pointer-events-none rounded-full shadow-[0_0_10px_white]"
        animate={{ x: position.x - 2, y: position.y - 2 }}
        transition={{ type: 'spring', damping: 40, stiffness: 800, mass: 0.1 }}
      />
    </>
  );
};

const GlitchText: React.FC<{ text: string; className?: string }> = ({ text, className }) => {
  const [displayText, setDisplayText] = useState(text);
  const chars = "X01!@#$%&*+=-_/";

  const trigger = () => {
    let iterations = 0;
    const interval = setInterval(() => {
      setDisplayText(prev => 
        prev.split("").map((c, i) => {
          if (i < iterations) return text[i];
          return chars[Math.floor(Math.random() * chars.length)];
        }).join("")
      );
      if (iterations >= text.length) clearInterval(interval);
      iterations += 1/4;
    }, 20);
  };

  useEffect(() => { trigger(); }, [text]);

  return <span className={className} onMouseEnter={trigger}>{displayText}</span>;
};

