const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  // Start Audio with High Gain and Stacking for Impact
  const initializeAudio = () => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // Base Bass Drone (Deep & Powerful)
      const droneBase = ctx.createOscillator();
      const droneBaseGain = ctx.createGain();
      droneBase.type = 'sawtooth';
      droneBase.frequency.setValueAtTime(32.70, ctx.currentTime); // C1
      droneBaseGain.gain.setValueAtTime(0.6, ctx.currentTime);
      droneBase.connect(droneBaseGain);
      droneBaseGain.connect(masterGain);
      droneBase.start();

      // Atmospheric Harmonic (Ghostly texture)
      const atmos = ctx.createOscillator();
      const atmosGain = ctx.createGain();
      atmos.type = 'sine';
      atmos.frequency.setValueAtTime(130.81, ctx.currentTime); // C3
      atmosGain.gain.setValueAtTime(0.2, ctx.currentTime);
      atmos.connect(atmosGain);
      atmosGain.connect(masterGain);
      atmos.start();

      // Pulsing Low Pass Filter (The "Dark" breath)
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(200, ctx.currentTime);
      filter.Q.setValueAtTime(15, ctx.currentTime);

      const pulseOsc = ctx.createOscillator();
      const pulseGain = ctx.createGain();
      pulseOsc.type = 'square';
      pulseOsc.frequency.setValueAtTime(1, ctx.currentTime); // 1Hz Pulse
      pulseGain.gain.setValueAtTime(100, ctx.currentTime);
      pulseOsc.connect(pulseGain);
      pulseGain.connect(filter.frequency);
      pulseOsc.start();

      // Final Master Unmute
      masterGain.gain.linearRampToValueAtTime(0.8, ctx.currentTime + 2); // High gain
      setHasEntered(true);
    } catch (e) {
      console.error("Audio failed", e);
      setHasEntered(true);
    }
  };

