const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  // "DARK" Series Atmospheric Sound Synthesis
  const initializeAudio = () => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // Deep Sub-Bass Drone (35Hz)
      const sub = ctx.createOscillator();
      const subGain = ctx.createGain();
      sub.type = 'sine';
      sub.frequency.setValueAtTime(35, ctx.currentTime);
      subGain.gain.setValueAtTime(0.6, ctx.currentTime);
      sub.connect(subGain);
      subGain.connect(masterGain);
      sub.start();

      // Ominous Middle Saw (Low-passed)
      const mid = ctx.createOscillator();
      const midFilter = ctx.createBiquadFilter();
      const midGain = ctx.createGain();
      mid.type = 'sawtooth';
      mid.frequency.setValueAtTime(45, ctx.currentTime);
      midFilter.type = 'lowpass';
      midFilter.frequency.setValueAtTime(120, ctx.currentTime);
      midGain.gain.setValueAtTime(0.3, ctx.currentTime);
      mid.connect(midFilter);
      midFilter.connect(midGain);
      midGain.connect(masterGain);
      mid.start();

      // High Shimmer Noise (Ben Frost style)
      const bufferSize = ctx.sampleRate * 2;
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
      const noise = ctx.createBufferSource();
      noise.buffer = buffer;
      noise.loop = true;
      const noiseFilter = ctx.createBiquadFilter();
      noiseFilter.type = 'bandpass';
      noiseFilter.frequency.setValueAtTime(8000, ctx.currentTime);
      noiseFilter.Q.setValueAtTime(10, ctx.currentTime);
      const noiseGain = ctx.createGain();
      noiseGain.gain.setValueAtTime(0.03, ctx.currentTime);
      noise.connect(noiseFilter);
      noiseFilter.connect(noiseGain);
      noiseGain.connect(masterGain);
      noise.start();

      // Pulse Modulation
      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.setValueAtTime(0.15, ctx.currentTime); // Slow breath
      lfoGain.gain.setValueAtTime(0.2, ctx.currentTime);
      lfo.connect(lfoGain);
      lfoGain.connect(masterGain.gain);
      lfo.start();

      masterGain.gain.linearRampToValueAtTime(0.7, ctx.currentTime + 3);
      setHasEntered(true);
    } catch (e) {
      console.warn("Audio Context Error", e);
      setHasEntered(true);
    }
  };

