const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  // DARK Series Sound Synthesis (Drones + Ticking)
  const initializeAudio = () => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // 1. Ominous Low Drone (30Hz)
      const lowDrone = ctx.createOscillator();
      const lowGain = ctx.createGain();
      lowDrone.type = 'sine';
      lowDrone.frequency.setValueAtTime(30.87, ctx.currentTime); // B0
      lowGain.gain.setValueAtTime(0.5, ctx.currentTime);
      lowDrone.connect(lowGain);
      lowGain.connect(masterGain);
      lowDrone.start();

      // 2. Harmonic Swell (Sawtooth through Filter)
      const swell = ctx.createOscillator();
      const swellFilter = ctx.createBiquadFilter();
      const swellGain = ctx.createGain();
      swell.type = 'sawtooth';
      swell.frequency.setValueAtTime(41.20, ctx.currentTime); // E1
      swellFilter.type = 'lowpass';
      swellFilter.frequency.setValueAtTime(100, ctx.currentTime);
      swellGain.gain.setValueAtTime(0.3, ctx.currentTime);
      swell.connect(swellFilter);
      swellFilter.connect(swellGain);
      swellGain.connect(masterGain);
      swell.start();

      // Slow Swell LFO
      const swellLfo = ctx.createOscillator();
      const swellLfoGain = ctx.createGain();
      swellLfo.frequency.setValueAtTime(0.08, ctx.currentTime); 
      swellLfoGain.gain.setValueAtTime(150, ctx.currentTime);
      swellLfo.connect(swellLfoGain);
      swellLfoGain.connect(swellFilter.frequency);
      swellLfo.start();

      // 3. The "DARK" Ticking Clock
      const tick = ctx.createOscillator();
      const tickGain = ctx.createGain();
      tick.type = 'square';
      tick.frequency.setValueAtTime(2000, ctx.currentTime);
      tickGain.gain.setValueAtTime(0, ctx.currentTime);
      tick.connect(tickGain);
      tickGain.connect(masterGain);
      tick.start();

      const tickLoop = () => {
        if (!audioCtxRef.current) return;
        const now = audioCtxRef.current.currentTime;
        tickGain.gain.setValueAtTime(0.02, now);
        tickGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02);
        setTimeout(tickLoop, 1000); // 1-second interval
      };
      tickLoop();

      // Initial Volume Ramp
      masterGain.gain.linearRampToValueAtTime(0.9, ctx.currentTime + 3); 
      setHasEntered(true);
    } catch (e) {
      console.warn("Audio Context init failed", e);
      setHasEntered(true);
    }
  };

  useEffect(() => {
    if (masterGainRef.current && audioCtxRef.current) {
      const target = isMuted ? 0.0001 : 0.9;
      masterGainRef.current.gain.exponentialRampToValueAtTime(target, audioCtxRef.current.currentTime + 1);
    }
  }, [isMuted]);

  return (
