const Cursor: React.FC = () => {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [isPointer, setIsPointer] = useState(false);

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      const target = e.target as HTMLElement;
      setIsPointer(
        window.getComputedStyle(target).cursor === 'pointer' || 
        target.closest('a') !== null || 
        target.closest('button') !== null
      );
    };
    window.addEventListener('mousemove', handleMove);
    return () => window.removeEventListener('mousemove', handleMove);
  }, []);

  return (
    <>
      <motion.div
        className="fixed top-0 left-0 w-8 h-8 border border-[#00ff41] z-[999999] pointer-events-none mix-blend-screen hidden lg:block"
        animate={{ 
          x: position.x - 16, 
          y: position.y - 16, 
          scale: isPointer ? 1.5 : 1,
          rotate: isPointer ? 90 : 0,
          borderColor: isPointer ? "#ff003c" : "#00ff41"
        }}
        transition={{ type: 'spring', damping: 30, stiffness: 500 }}
      />
      <motion.div
        className="fixed top-0 left-0 w-1 h-1 bg-white z-[999999] pointer-events-none rounded-full hidden lg:block"
        animate={{ x: position.x - 2, y: position.y - 2 }}
        transition={{ type: 'spring', damping: 40, stiffness: 1000 }}
      />
    </>
  );
};

