const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  // "DARK" Series Atmosphere Audio Engine
  const initializeAudio = () => {
    try {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // 1. Low Drone (DARK Sub frequency)
      const lowDrone = ctx.createOscillator();
      lowDrone.type = 'sine';
      lowDrone.frequency.setValueAtTime(32.7, ctx.currentTime); // C1
      const lowGain = ctx.createGain();
      lowGain.gain.setValueAtTime(0.5, ctx.currentTime);
      lowDrone.connect(lowGain);
      lowGain.connect(masterGain);
      lowDrone.start();

      // 2. Ticking Clock (Metallic pulse)
      const tick = ctx.createOscillator();
      const tickGain = ctx.createGain();
      tick.type = 'square';
      tick.frequency.setValueAtTime(2200, ctx.currentTime);
      tick.connect(tickGain);
      tickGain.connect(masterGain);
      tick.start();

      const runTick = () => {
        if (!audioCtxRef.current) return;
        const now = audioCtxRef.current.currentTime;
        // The ticking sound has a double-hit feel in the series
        tickGain.gain.setValueAtTime(0.04, now);
        tickGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.04);

        tickGain.gain.setValueAtTime(0.02, now + 0.1);
        tickGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14);

        setTimeout(runTick, 1000); 
      };
      runTick();

      // 3. Middle swell (Sawtooth through a pulsing low-pass filter)
      const midSwell = ctx.createOscillator();
      midSwell.type = 'sawtooth';
      midSwell.frequency.setValueAtTime(43.65, ctx.currentTime); // F1
      const lowPass = ctx.createBiquadFilter();
      lowPass.type = 'lowpass';
      lowPass.frequency.setValueAtTime(80, ctx.currentTime);
      lowPass.Q.setValueAtTime(10, ctx.currentTime);

      const midGain = ctx.createGain();
      midGain.gain.setValueAtTime(0.2, ctx.currentTime);

      midSwell.connect(lowPass);
      lowPass.connect(midGain);
      midGain.connect(masterGain);
      midSwell.start();

      // Filter modulation for that breathing effect
      const lfo = ctx.createOscillator();
      lfo.frequency.setValueAtTime(0.08, ctx.currentTime); // Slow breathing
      const lfoGain = ctx.createGain();
      lfoGain.gain.setValueAtTime(120, ctx.currentTime);
      lfo.connect(lfoGain);
      lfoGain.connect(lowPass.frequency);
      lfo.start();

      // Master ramp up
      masterGain.gain.linearRampToValueAtTime(0.9, ctx.currentTime + 3); 
      setHasEntered(true);
    } catch (e) {
      console.error("Audio engine failure", e);
      setHasEntered(true);
    }
  };

  useEffect(() => {
    if (masterGainRef.current && audioCtxRef.current) {
      const target = isMuted ? 0.0001 : 0.9;
      masterGainRef.current.gain.exponentialRampToValueAtTime(target, audioCtxRef.current.currentTime + 1.2);
    }
  }, [isMuted]);

  return (
    <div className="min-h-screen relative overflow-hidden bg-black text-white selection:bg-emerald-500/30">
      <AnimatePresence mode="wait">
        {!hasEntered && <EntryScreen onEnter={initializeAudio} />}
