const EntryScreen: React.FC<EntryScreenProps> = ({ onEnter }) => {
  const [loading, setLoading] = useState(0);
  const [status, setStatus] = useState("CORE_INIT...");
  const [isReady, setIsReady] = useState(false);

  const statuses = [
    "CORE_INIT...",
    "HANDSHAKE_P2P...",
    "DECRYPT_NODES...",
    "BYPASS_FWALL...",
    "FETCH_ID...",
    "AUTH_GRANTED"
  ];

  useEffect(() => {
    const timer = setTimeout(() => {
      const interval = setInterval(() => {
        setLoading(prev => {
          if (prev >= 100) {
            clearInterval(interval);
            setIsReady(true);
            setStatus("DEPLOYMENT_READY");
            return 100;
          }
          const next = Math.min(prev + (Math.random() * 25 + 15), 100);
          setStatus(statuses[Math.floor((next / 100) * statuses.length)] || statuses[statuses.length - 1]);
          return next;
        });
      }, 80);
      return () => clearInterval(interval);
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  return (
    <motion.div 
      exit={{ opacity: 0, scale: 1.5, filter: "blur(100px)", transition: { duration: 1.2, ease: "circIn" } }}
      className="fixed inset-0 z-[1000000] bg-black flex flex-col items-center justify-center overflow-hidden"
    >
      <div className="absolute inset-0 opacity-10 pointer-events-none grid grid-cols-6 md:grid-cols-12 gap-8 p-12 text-[10px] mono text-[#00ff41] select-none">
        {Array.from({ length: 72 }).map((_, i) => (
          <motion.div 
            key={i}
            animate={{ opacity: [0, 1, 0] }}
            transition={{ duration: Math.random() * 2 + 1, repeat: Infinity, delay: Math.random() * 2 }}
            className="flex flex-col gap-2"
          >
            {Array.from({ length: 10 }).map((_, j) => (
              <span key={j}>{Math.round(Math.random())}</span>
            ))}
          </motion.div>
        ))}
      </div>

      <div className="relative z-10 w-full max-w-xl px-10 flex flex-col items-center text-center">
        <motion.div 
          initial={{ y: 30, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 1 }}
