import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface TooltipProps {
  content: string;
  metadata?: string;
  children: React.ReactNode;
}

const Tooltip: React.FC<TooltipProps> = ({ content, metadata, children }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [coords, setCoords] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMouseEnter = () => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      setCoords({
        x: rect.left + rect.width / 2,
        y: rect.top,
      });
    }
    setIsVisible(true);
  };

  return (
    <div 
      ref={containerRef}
      className="relative flex items-center justify-center"
      onMouseEnter={handleMouseEnter}
      onMouseLeave={() => setIsVisible(false)}
      onFocus={handleMouseEnter}
      onBlur={() => setIsVisible(false)}
    >
      {children}
      <AnimatePresence>
        {isVisible && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 15 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 15 }}
            transition={{ type: 'spring', damping: 25, stiffness: 400 }}
            className="fixed z-[1000000] pointer-events-none -translate-x-1/2 -translate-y-full mt-[-1rem]"
            style={{ 
              left: coords.x, 
              top: coords.y - 12
            }}
          >
            <div className="bg-slate-900 border-2 border-emerald-500/60 backdrop-blur-3xl p-5 md:p-6 shadow-[0_0_80px_rgba(0,255,65,0.3)] min-w-[280px] md:min-w-[320px] max-w-[400px] rounded-sm relative overflow-hidden">
              <div className="flex justify-between items-center mb-5 pb-3 border-b-2 border-slate-800">
                <div className="flex items-center gap-3">
                  <div className="w-2.5 h-2.5 bg-emerald-500 shadow-[0_0_12px_#00ff41] rounded-full animate-pulse" />
                  <span className="text-[11px] mono text-emerald-500 font-black tracking-[0.5em] uppercase whitespace-nowrap">SEC_PACKET</span>
                </div>
                {metadata && <span className="text-[9px] mono text-slate-500 font-black tracking-widest uppercase">[{metadata}]</span>}
              </div>

              <p className="text-[14px] md:text-[16px] mono text-white leading-relaxed font-medium tracking-tight">
                {content}
              </p>

              {/* Tactical Indicators */}
              <div className="absolute top-1 left-1 w-3 h-3 border-t-2 border-l-2 border-emerald-500/40" />
              <div className="absolute bottom-1 right-1 w-3 h-3 border-b-2 border-r-2 border-emerald-500/40" />

