      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // 1. Low Drone (Sub frequency)
      const lowDrone = ctx.createOscillator();
      lowDrone.type = 'sine';
      lowDrone.frequency.setValueAtTime(32.7, ctx.currentTime);
      const lowGain = ctx.createGain();
      lowGain.gain.setValueAtTime(0.3, ctx.currentTime);
      lowDrone.connect(lowGain);
      lowGain.connect(masterGain);
      lowDrone.start();

      // 2. Ticking (Precise)
      const tick = ctx.createOscillator();
      const tickGain = ctx.createGain();
      tick.type = 'square';
      tick.frequency.setValueAtTime(1800, ctx.currentTime);
      tick.connect(tickGain);
      tickGain.connect(masterGain);
