const SecurityTerminal: React.FC<SecurityTerminalProps> = ({ isOpen, onClose, audioCtx }) => {
  const [input, setInput] = useState("");
  const [history, setHistory] = useState<{ type: 'user' | 'ai', text: string }[]>([
    { type: 'ai', text: "SEC_OPERATIVE_v4 ONLINE. AUTHORIZATION GRANTED." },
    { type: 'ai', text: "Awaiting tactical commands..." }
  ]);
  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Sound Utility Functions
  const playSound = (freq: number, type: OscillatorType, duration: number, gainValue: number = 0.1) => {
    if (!audioCtx) return;
    const osc = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
    g.gain.setValueAtTime(gainValue, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + duration);
    osc.connect(g);
    g.connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + duration);
  };

  const playOpenSound = () => {
    playSound(440, 'sine', 0.2, 0.1);
    setTimeout(() => playSound(880, 'sine', 0.1, 0.05), 50);
  };

  const playCloseSound = () => {
    playSound(440, 'sine', 0.3, 0.1);
    setTimeout(() => playSound(220, 'sine', 0.4, 0.05), 100);
  };

  const playSendSound = () => {
    playSound(1200, 'square', 0.05, 0.03);
  };

  const playReceiveSound = () => {
    playSound(900, 'sine', 0.1, 0.05);
    setTimeout(() => playSound(1100, 'sine', 0.05, 0.05), 40);
  };

  useEffect(() => {
    if (isOpen) {
      playOpenSound();
      scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
    }
  }, [isOpen]);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [history]);

  const handleClose = () => {
    playCloseSound();
    onClose();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isProcessing) return;

    const userMsg = input.trim();
    setInput("");
    playSendSound();
    setHistory(prev => [...prev, { type: 'user', text: userMsg }]);
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `You are the AI interface for Jinesh Chudasama's portfolio. 
        Context: Jinesh is a Security professional (Bandhan AMC) and also a professional actor. 
        Tone: Futuristic, security-oriented, brief, highly efficient. 
        User query: ${userMsg}`,
        config: { systemInstruction: "Act as a security terminal. Use monospaced terminology. Keep responses short." }
      });

      playReceiveSound();
      setHistory(prev => [...prev, { type: 'ai', text: response.text || "PROTOCOL_ERROR: NO_RESPONSE_RECOGNIZED" }]);
    } catch (err) {
      setHistory(prev => [...prev, { type: 'ai', text: "CRITICAL_ERROR: UPLINK_TIMEOUT. CHECK_ENCRYPTION_KEYS." }]);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div 
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          className="fixed inset-0 z-[1000000] flex items-center justify-center p-4 md:p-10 pointer-events-none"
        >
          <div className="w-full max-w-4xl h-[80vh] bg-black/90 backdrop-blur-3xl border border-emerald-500/30 shadow-[0_0_100px_rgba(16,185,129,0.2)] rounded-sm flex flex-col overflow-hidden pointer-events-auto relative">

            {/* Terminal Header */}
            <div className="flex items-center justify-between px-6 py-4 border-b border-emerald-500/20 bg-zinc-950/50">
              <div className="flex items-center gap-4">
                <Terminal size={20} className="text-emerald-500" />
                <div className="flex flex-col">
                  <span className="text-[10px] mono text-white font-black tracking-widest uppercase">SEC_SHELL // ROOT_TERMINAL</span>
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_5px_#10b981]" />
                    <span className="text-[8px] text-zinc-500 font-bold uppercase tracking-tighter">Uplink: Active_AES_256</span>
                  </div>
                </div>
              </div>
              <button onClick={handleClose} className="p-2 hover:bg-red-500/20 text-zinc-500 hover:text-red-500 transition-all rounded-sm">
                <X size={20} />
              </button>
            </div>

            {/* Terminal Logs */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 mono text-sm scroll-smooth bg-[radial-gradient(circle_at_center,rgba(0,255,65,0.02)_0%,transparent_100%)]">
              {history.map((msg, i) => (
                <motion.div 
                  initial={{ opacity: 0, x: -10 }} 
                  animate={{ opacity: 1, x: 0 }} 
                  key={i} 
                  className={`flex gap-4 ${msg.type === 'user' ? 'opacity-80' : ''}`}
                >
                  <span className={`shrink-0 font-black ${msg.type === 'user' ? 'text-blue-500' : 'text-emerald-500'}`}>
                    {msg.type === 'user' ? '[GUEST@OPS]:' : '[SYS_CORE]:'}
                  </span>
                  <p className={`${msg.type === 'user' ? 'text-zinc-300' : 'text-emerald-400'} leading-relaxed`}>
                    {msg.text}
                  </p>
                </motion.div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-2 text-emerald-500 animate-pulse">
                  <Cpu size={14} /> <span>PROCESSING_PACKET...</span>
                </div>
              )}
            </div>

            {/* Terminal Input */}
            <form onSubmit={handleSubmit} className="p-6 border-t border-emerald-500/20 bg-zinc-950/50 flex gap-4">
               <span className="text-emerald-500 font-black mono flex items-center gap-2">
                 <Zap size={14} /> $
               </span>
               <input 
                 autoFocus
                 value={input}
                 onChange={(e) => setInput(e.target.value)}
                 className="flex-1 bg-transparent border-none outline-none mono text-white placeholder:text-zinc-800"
                 placeholder="Enter mission protocol or query intelligence..."
               />
               <button type="submit" disabled={isProcessing} className="text-zinc-600 hover:text-emerald-500 transition-colors">
                 <Send size={20} />
               </button>
            </form>

            {/* Visual HUD Decorations */}
            <div className="absolute top-2 right-1/2 translate-x-1/2 opacity-20 pointer-events-none hidden md:flex gap-1">
               {Array.from({length: 20}).map((_, i) => <div key={i} className="w-0.5 h-1 bg-emerald-500" />)}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

