import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Terminal, X, Send, Cpu, Activity, Zap, Shield, Globe } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface SecurityTerminalProps {
  isOpen: boolean;
  onClose: () => void;
  audioCtx: AudioContext | null;
}

const SecurityTerminal: React.FC<SecurityTerminalProps> = ({ isOpen, onClose, audioCtx }) => {
  const [input, setInput] = useState("");
  const [history, setHistory] = useState<{ type: 'user' | 'ai', text: string }[]>([
    { type: 'ai', text: "NEURAL_LINK_ESTABLISHED. ROOT_SHELL_v4.2 ACTIVE." },
    { type: 'ai', text: "System monitoring Jinesh Chudasama's strategic archives. State your query." }
  ]);
  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Advanced Sound Utility
  const playBlip = (freqs: number[], type: OscillatorType, duration: number, gainValue: number = 0.1) => {
    if (!audioCtx || audioCtx.state === 'suspended') return;

    const now = audioCtx.currentTime;
    const g = audioCtx.createGain();
    g.gain.setValueAtTime(gainValue, now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    g.connect(audioCtx.destination);

    freqs.forEach((freq, idx) => {
      const osc = audioCtx.createOscillator();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, now + (idx * 0.05));
      osc.connect(g);
      osc.start(now + (idx * 0.05));
      osc.stop(now + duration + (idx * 0.05));
    });
  };

  const playOpenSound = () => playBlip([440, 880, 1760], 'sine', 0.4, 0.15);
  const playCloseSound = () => playBlip([1760, 880, 440], 'sine', 0.5, 0.1);
  const playSendSound = () => playBlip([2200, 4400], 'square', 0.08, 0.05);
  const playReceiveSound = () => playBlip([880, 1100], 'sine', 0.2, 0.08);

  useEffect(() => {
    if (isOpen) {
      playOpenSound();
      scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
    }
  }, [isOpen]);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [history]);

  const handleClose = () => {
    playCloseSound();
    onClose();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isProcessing) return;

    const userMsg = input.trim();
    setInput("");
    playSendSound();
    setHistory(prev => [...prev, { type: 'user', text: userMsg }]);
    setIsProcessing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Context: Security Portfolio of Jinesh Chudasama (VAPT at Bandhan AMC, Actor).
        Task: Respond as a high-security tactical AI. Use short, efficient, monospaced tech jargon where appropriate.
        User Query: ${userMsg}`,
        config: { systemInstruction: "Act as an encrypted tactical shell. Keep responses concise and futuristic." }
      });

      playReceiveSound();
      setHistory(prev => [...prev, { type: 'ai', text: response.text || "COMM_ERROR: EMPTY_PACKET" }]);
    } catch (err) {
      setHistory(prev => [...prev, { type: 'ai', text: "UPLINK_FAILURE: SIGNAL_INTERCEPTED_OR_TIMEOUT." }]);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div 
          initial={{ opacity: 0, scale: 0.9, filter: 'blur(10px)' }}
          animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
          exit={{ opacity: 0, scale: 1.1, filter: 'blur(20px)' }}
          className="fixed inset-0 z-[1000000] flex items-center justify-center p-4 md:p-12 pointer-events-none"
        >
          <div className="w-full max-w-5xl h-[85vh] bg-black/95 backdrop-blur-3xl border-2 border-emerald-500/30 shadow-[0_0_150px_rgba(16,185,129,0.25)] rounded-sm flex flex-col overflow-hidden pointer-events-auto relative">

            {/* Header */}
            <div className="flex items-center justify-between px-8 py-6 border-b border-emerald-500/20 bg-zinc-950/80">
              <div className="flex items-center gap-6">
                <div className="p-3 bg-emerald-500/10 rounded-sm">
                   <Terminal size={24} className="text-emerald-500" />
                </div>
                <div className="flex flex-col">
                  <span className="text-[12px] mono text-white font-black tracking-widest uppercase">SEC_OPS_TERMINAL // GRID_UPLINK</span>
                  <div className="flex items-center gap-3">
                    <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_#10b981]" />
                    <span className="text-[10px] text-zinc-500 font-black uppercase tracking-tighter">Status: Active_Trace_Clean</span>
                  </div>
                </div>
              </div>
              <button onClick={handleClose} className="p-3 hover:bg-red-500/20 text-zinc-600 hover:text-red-500 transition-all rounded-full">
                <X size={24} />
              </button>
            </div>

            {/* Logs Area */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-6 mono text-[15px] scroll-smooth bg-[radial-gradient(circle_at_center,rgba(0,255,65,0.03)_0%,transparent_100%)]">
              {history.map((msg, i) => (
                <motion.div 
                  initial={{ opacity: 0, x: -15 }} 
                  animate={{ opacity: 1, x: 0 }} 
                  key={i} 
                  className={`flex gap-6 ${msg.type === 'user' ? 'bg-zinc-900/40 p-4 rounded-sm' : ''}`}
                >
                  <span className={`shrink-0 font-black text-[12px] pt-1 ${msg.type === 'user' ? 'text-blue-500' : 'text-emerald-500'}`}>
                    {msg.type === 'user' ? '[GUEST@OPS]:' : '[SYS_CORE]:'}
                  </span>
                  <p className={`${msg.type === 'user' ? 'text-zinc-300 font-light' : 'text-emerald-400 font-medium'} leading-relaxed max-w-4xl`}>
                    {msg.text}
                  </p>
                </motion.div>
              ))}
              {isProcessing && (
                <div className="flex items-center gap-3 text-emerald-500/50 animate-pulse italic">
                  <Cpu size={18} className="animate-spin" /> <span>ANALYZING_TACTICAL_PACKET...</span>
                </div>
              )}
            </div>

            {/* Input Bar */}
            <form onSubmit={handleSubmit} className="p-8 border-t border-emerald-500/20 bg-zinc-950/80 flex gap-6 items-center">
               <span className="text-emerald-500 font-black mono text-xl flex items-center gap-3">
                 <Zap size={20} className="text-emerald-500 animate-pulse" /> $
               </span>
               <input 
                 autoFocus
                 value={input}
                 onChange={(e) => setInput(e.target.value)}
                 className="flex-1 bg-transparent border-none outline-none mono text-white text-lg placeholder:text-zinc-800"
                 placeholder="Enter mission command or query system archives..."
               />
               <button type="submit" disabled={isProcessing} className="p-4 bg-emerald-500/5 hover:bg-emerald-500/20 text-zinc-500 hover:text-emerald-500 transition-all rounded-sm">
                 <Send size={24} />
               </button>
            </form>

            {/* HUD Scan Effect Overlay */}
            <div className="absolute inset-0 pointer-events-none opacity-5 bg-[linear-gradient(transparent_0%,rgba(0,255,65,0.5)_50%,transparent_100%)] bg-[size:100%_4px] animate-scan" />
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default SecurityTerminal;

