import React, { useState, useEffect, useRef } from 'react';
import { motion, useScroll, useSpring, AnimatePresence, useTransform, useMotionValue } from 'framer-motion';
// Added Globe to the lucide-react import list
import { Shield, Mail, GraduationCap, Award, Film, Lock, Activity, Terminal, Zap, Fingerprint, Server, Github, Linkedin, Binary, MapPin, Volume2, VolumeX, BookOpen, Clock, Sun, Moon, ArrowDown, Target, Network, Cpu, Globe } from 'lucide-react';
import { FadeIn, SlideIn, ScaleIn } from './components/FramerComponents';
import EntryScreen from './components/EntryScreen';
import Tooltip from './components/Tooltip';
import SecurityTerminal from './components/SecurityTerminal';
import { PERSONAL_INFO, MISSIONS, ACHIEVEMENTS, NAV_LINKS, SOCIAL_LINKS, ARSENAL } from './constants';

const Cursor: React.FC = () => {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [isPointer, setIsPointer] = useState(false);

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      const target = e.target as HTMLElement;
      setIsPointer(
        window.getComputedStyle(target).cursor === 'pointer' || 
        target.closest('a') !== null || 
        target.closest('button') !== null
      );
    };
    window.addEventListener('mousemove', handleMove);
    return () => window.removeEventListener('mousemove', handleMove);
  }, []);

  return (
    <>
      <motion.div
        className="fixed top-0 left-0 w-12 h-12 border border-[#00ff41] z-[999999] pointer-events-none mix-blend-screen hidden lg:block rounded-sm"
        animate={{ 
          x: position.x - 24, 
          y: position.y - 24, 
          scale: isPointer ? 1.5 : 1,
          rotate: isPointer ? 90 : 0,
          borderColor: isPointer ? "#ff003c" : "#00ff41"
        }}
        transition={{ type: 'spring', damping: 20, stiffness: 300 }}
      />
      <motion.div
        className="fixed top-0 left-0 w-1.5 h-1.5 bg-white z-[999999] pointer-events-none rounded-full hidden lg:block shadow-[0_0_10px_#fff]"
        animate={{ x: position.x - 3, y: position.y - 3 }}
        transition={{ type: 'spring', damping: 30, stiffness: 800 }}
      />
    </>
  );
};

const HUDCircle: React.FC<{ size: string; color: string; speed: number; opacity: number; reverse?: boolean }> = ({ size, color, speed, opacity, reverse = false }) => (
  <motion.div
    animate={{ rotate: reverse ? -360 : 360 }}
    transition={{ duration: speed, repeat: Infinity, ease: "linear" }}
    className={`absolute rounded-full border border-dashed ${size} pointer-events-none`}
    style={{ borderColor: color, opacity }}
  />
);

const App: React.FC = () => {
  const [hasEntered, setHasEntered] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isDark, setIsDark] = useState(true);
  const [isTerminalOpen, setIsTerminalOpen] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const masterGainRef = useRef<GainNode | null>(null);

  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 100, damping: 30, restDelta: 0.001 });

  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);
  const rotateX = useTransform(mouseY, [-500, 500], [10, -10]);
  const rotateY = useTransform(mouseX, [-500, 500], [-10, 10]);

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left - rect.width / 2;
    const y = e.clientY - rect.top - rect.height / 2;
    mouseX.set(x);
    mouseY.set(y);
  };

  const toggleTheme = () => {
    setIsDark(!isDark);
    document.documentElement.classList.toggle('dark');
  };

  const initializeAudio = () => {
    try {
      if (audioCtxRef.current) return;
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const masterGain = ctx.createGain();
      masterGain.gain.setValueAtTime(0, ctx.currentTime);
      masterGain.connect(ctx.destination);
      masterGainRef.current = masterGain;

      // 1. Sub Drone
      const sub = ctx.createOscillator();
      sub.type = 'sine';
      sub.frequency.setValueAtTime(32.7, ctx.currentTime);
      const subGain = ctx.createGain();
      subGain.gain.setValueAtTime(0.4, ctx.currentTime);
      sub.connect(subGain);
      subGain.connect(masterGain);
      sub.start();

      // 2. Constant Buzz (Dark Webseries Aesthetic)
      const buzz = ctx.createOscillator();
      buzz.type = 'sawtooth';
      buzz.frequency.setValueAtTime(55, ctx.currentTime);
      const lpFilter = ctx.createBiquadFilter();
      lpFilter.type = 'lowpass';
      lpFilter.frequency.setValueAtTime(100, ctx.currentTime);
      const buzzGain = ctx.createGain();
      buzzGain.gain.setValueAtTime(0.15, ctx.currentTime);
      buzz.connect(lpFilter);
      lpFilter.connect(buzzGain);
      buzzGain.connect(masterGain);
      buzz.start();

      // 3. Precise Ticking
      const tick = ctx.createOscillator();
      const tickGain = ctx.createGain();
      tick.type = 'square';
      tick.frequency.setValueAtTime(1800, ctx.currentTime);
      tick.connect(tickGain);
      tickGain.connect(masterGain);
      tick.start();

      const runTick = () => {
        if (!audioCtxRef.current) return;
        const now = audioCtxRef.current.currentTime;
        tickGain.gain.setValueAtTime(0.04, now);
        tickGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05);
        setTimeout(runTick, 1000); 
      };
      runTick();

      masterGain.gain.linearRampToValueAtTime(0.8, ctx.currentTime + 3);
      setHasEntered(true);
    } catch (e) {
      setHasEntered(true);
    }
  };

  useEffect(() => {
    if (masterGainRef.current && audioCtxRef.current) {
      const target = isMuted ? 0.0001 : 0.8;
      masterGainRef.current.gain.exponentialRampToValueAtTime(target, audioCtxRef.current.currentTime + 1.2);
    }
  }, [isMuted]);

  return (
    <div className={`min-h-screen relative transition-colors duration-1000 font-mono ${isDark ? 'bg-black text-white' : 'bg-slate-50 text-slate-900'}`}>
      <AnimatePresence mode="wait">
        {!hasEntered && <EntryScreen onEnter={initializeAudio} />}
      </AnimatePresence>

      <Cursor />
      <SecurityTerminal isOpen={isTerminalOpen} onClose={() => setIsTerminalOpen(false)} audioCtx={audioCtxRef.current} />

      <div className="fixed top-0 left-0 right-0 h-[3px] bg-emerald-500/10 z-[6000]">
        <motion.div className="h-full bg-emerald-500 origin-left shadow-[0_0_15px_#10b981]" style={{ scaleX }} />
      </div>

      <header className="fixed top-0 left-0 w-full z-[5000] px-6 py-6 md:px-12 flex justify-between items-center pointer-events-none">
        <motion.div 
          initial={{ x: -20, opacity: 0 }}
          animate={{ x: 0, opacity: 1 }}
          className="pointer-events-auto bg-black/80 backdrop-blur-3xl border border-white/5 p-4 flex flex-col gap-1 shadow-2xl"
        >
          <div className="flex items-center gap-3">
            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_#10b981]" />
            <span className="text-white text-[10px] font-black tracking-[0.4em] uppercase">SYSTEM.OPERATIVE // v4.2.0</span>
          </div>
          <span className="text-zinc-500 text-[8px] uppercase tracking-widest font-bold font-mono">ENCRYPT_KEY: SHAKE_512_AES</span>
        </motion.div>

        <div className="flex gap-4 pointer-events-auto">
          <div className="hidden md:flex items-center gap-8 mr-6 bg-black/20 backdrop-blur-md px-8 py-2 rounded-full border border-white/5">
            {NAV_LINKS.map((link) => (
              <a 
                key={link.name} 
                href={link.href} 
                className="text-zinc-400 hover:text-emerald-500 transition-colors text-[10px] font-black tracking-widest uppercase"
              >
                {link.name}
              </a>
            ))}
          </div>

          <div className="flex gap-2 p-2 bg-black/90 rounded-sm border border-white/10 shadow-2xl">
            <Tooltip content="Toggle Tactical Terminal" metadata="AI_SHELL">
               <button onClick={() => setIsTerminalOpen(true)} className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-emerald-500 transition-all bg-white/5">
                 <Terminal size={18} />
               </button>
            </Tooltip>
            <button onClick={toggleTheme} className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white transition-all bg-white/5">
              {isDark ? <Sun size={18} /> : <Moon size={18} />}
            </button>
            <button onClick={() => setIsMuted(!isMuted)} className="w-10 h-10 flex items-center justify-center text-zinc-400 hover:text-white transition-all bg-white/5">
              {isMuted ? <VolumeX size={18} /> : <Volume2 size={18} className="text-emerald-500" />}
            </button>
          </div>
        </div>
      </header>

      <main className={`relative z-10 ${hasEntered ? 'opacity-100' : 'opacity-0'} transition-opacity duration-1000`} onMouseMove={handleMouseMove}>

        {/* REDEFINED HOME SECTION: THE NEURAL GRID */}
        <section id="identity" className="min-h-screen flex items-center justify-center relative overflow-hidden px-6 pt-32 pb-20">

          {/* Background Elements */}
          <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
            <HUDCircle size="w-[90vw] h-[90vw]" color="rgba(16, 185, 129, 0.1)" speed={60} opacity={0.2} />
            <HUDCircle size="w-[70vw] h-[70vw]" color="rgba(16, 185, 129, 0.05)" speed={40} opacity={0.15} reverse />
            <HUDCircle size="w-[50vw] h-[50vw]" color="rgba(16, 185, 129, 0.15)" speed={25} opacity={0.3} />

            <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[60vw] h-[60vw] ${isDark ? 'bg-emerald-500' : 'bg-emerald-200'}/10 rounded-full blur-[200px] animate-pulse`} />

            {/* The Buzzing Grid Overlay */}
            <motion.div 
              animate={{ y: [-50, 0, -50] }} 
              transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
              className="absolute inset-0 opacity-10 bg-[linear-gradient(transparent_1px,rgba(255,255,255,0.05)_1px),linear-gradient(90deg,transparent_1px,rgba(255,255,255,0.05)_1px)] bg-[size:40px_40px]" 
            />
          </div>

          <div className="container mx-auto relative z-10 flex flex-col lg:flex-row items-center justify-between gap-12 lg:gap-24">

            {/* Content Left */}
            <div className="flex flex-col gap-12 max-w-2xl text-center lg:text-left items-center lg:items-start">
              <FadeIn className="space-y-6">
                <div className="flex items-center justify-center lg:justify-start gap-4 text-emerald-500 font-black tracking-[0.6em] text-[11px] uppercase">
                   <Target size={22} className="animate-pulse" />
                   <span>SEC_CLEARENCE: TOP_TIER_VAPT</span>
                </div>

                <h1 className="text-7xl md:text-9xl lg:text-[11rem] font-grotesk font-black uppercase tracking-tighter text-white leading-none relative">
                   <motion.span 
                    style={{ x: useTransform(mouseX, [-500, 500], [-30, 30]) }}
                    className="block text-white hover:hero-glitch transition-all"
                   >JINESH</motion.span>
                   <motion.span 
                    style={{ x: useTransform(mouseX, [-500, 500], [30, -30]) }}
                    className={`block ${isDark ? 'text-zinc-900' : 'text-slate-100'} hover:text-white transition-colors duration-700`}
                   >CHUDASAMA</motion.span>
                </h1>
              </FadeIn>

              <FadeIn delay={0.2} className="space-y-10">
                <p className={`text-2xl md:text-4xl font-grotesk ${isDark ? 'text-zinc-400' : 'text-slate-600'} font-light leading-snug`}>
                  {PERSONAL_INFO.title}
                  <br />
                  <span className="text-zinc-500 text-xl md:text-2xl mt-6 block italic border-l-4 border-emerald-500/30 pl-8 font-mono">
                    "{PERSONAL_INFO.tagline}"
                  </span>
                </p>

                <div className="flex flex-wrap justify-center lg:justify-start gap-8 items-center">
                  <Tooltip content="Launch Operative Intelligence" metadata="ROOT">
                    <motion.a 
                      href="#missions"
                      whileHover={{ scale: 1.05, backgroundColor: "#00ff41", color: "#000", boxShadow: "0 0 50px rgba(0,255,65,0.4)" }}
                      className="px-14 py-6 border-2 border-emerald-500 text-emerald-500 font-black uppercase tracking-[0.5em] text-[13px] flex items-center gap-5 transition-all shadow-2xl"
                    >
                      DEPLOY ARCHIVES <Binary size={22} />
                    </motion.a>
                  </Tooltip>

                  <div className="flex gap-5">
                    {SOCIAL_LINKS.map(link => (
                      <motion.a 
                        key={link.name}
                        href={link.url}
                        target="_blank"
                        whileHover={{ y: -8, scale: 1.1, borderColor: "#00a2ff", color: "#00a2ff" }}
                        className="w-16 h-16 border-2 border-zinc-800 flex items-center justify-center text-zinc-500 transition-all rounded-sm bg-black/60 backdrop-blur-xl shadow-xl"
                      >
                        {link.icon}
                      </motion.a>
                    ))}
                  </div>
                </div>
              </FadeIn>
            </div>

            {/* Visual Core Right */}
            <div className="relative w-full max-w-md lg:max-w-xl aspect-square flex items-center justify-center">
              <motion.div style={{ rotateX, rotateY }} className="w-full h-full relative">

                {/* HUD Elements */}
                <div className="absolute inset-0 flex items-center justify-center">
                  <motion.div animate={{ rotate: 360 }} transition={{ duration: 20, repeat: Infinity, ease: "linear" }} className="w-[110%] h-[110%] border-4 border-dotted border-emerald-500/10 rounded-full" />
                  <motion.div animate={{ rotate: -360 }} transition={{ duration: 40, repeat: Infinity, ease: "linear" }} className="absolute w-[90%] h-[90%] border-2 border-emerald-500/20 rounded-full" />

                  <motion.div 
                    whileHover={{ scale: 1.15, rotate: 5 }}
                    className="absolute w-56 h-56 md:w-72 md:h-72 bg-black border-4 border-zinc-800 rounded-full flex items-center justify-center shadow-[0_0_100px_rgba(16,185,129,0.3)] overflow-hidden group cursor-crosshair z-20"
                  >
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.2)_0%,transparent_75%)] opacity-0 group-hover:opacity-100 transition-opacity" />
                    <Fingerprint size={160} className="text-emerald-500/30 group-hover:text-emerald-500 transition-all duration-700 group-hover:scale-125" />
                    <motion.div animate={{ top: ['-20%', '120%'] }} transition={{ duration: 3, repeat: Infinity, ease: "linear" }} className="absolute left-0 right-0 h-[4px] bg-emerald-500/40 blur-[4px] shadow-[0_0_20px_#10b981]" />
                  </motion.div>

                  {/* Operational Telemetry */}
                  <div className="absolute -top-10 -right-10 mono text-[10px] text-zinc-600 bg-black/60 p-4 border border-white/5 backdrop-blur-xl hidden md:block">
                     <div className="flex justify-between gap-10 border-b border-zinc-800 pb-2 mb-2">
                        <span>CPU_LOAD:</span> <span className="text-emerald-500">2.4%</span>
                     </div>
                     <div className="flex justify-between gap-10">
                        <span>THREATS:</span> <span className="text-red-500">NULL</span>
                     </div>
                  </div>
                </div>
              </motion.div>
            </div>
          </div>

          <motion.div 
            animate={{ y: [0, 12, 0], opacity: [0.3, 0.7, 0.3] }} 
            transition={{ duration: 2.5, repeat: Infinity }} 
            className="absolute bottom-12 left-1/2 -translate-x-1/2 flex flex-col items-center gap-5 text-zinc-500 pointer-events-none"
          >
            <span className="mono text-[11px] uppercase tracking-[0.6em] font-black">Decrypt for More</span>
            <div className="w-[1.5px] h-20 bg-gradient-to-b from-emerald-500 to-transparent" />
          </motion.div>
        </section>

