                       </h3>
                       <div className="space-y-12">
                          {cat.skills.map(skill => (
                            <div key={skill.name} className="space-y-5">
                               <div className="flex justify-between items-end mono">
                                  <div className="space-y-2">
                                     <p className="text-[15px] font-black text-white uppercase tracking-wider">{skill.name}</p>
                                     <p className="text-[10px] text-zinc-500 uppercase tracking-tighter">{skill.detail}</p>
                                  </div>
                                  <span className="text-emerald-500 text-[12px] font-black">{skill.level}%</span>
                               </div>
                               <div className="h-[3px] bg-zinc-900 w-full relative overflow-hidden">
                                  <motion.div 
                                    initial={{ width: 0 }} 
                                    whileInView={{ width: `${skill.level}%` }} 
                                    transition={{ duration: 2, ease: "circOut" }}
                                    className="h-full bg-current shadow-[0_0_15px_currentColor]"
                                    style={{ color: cat.icon.props.className.includes('red') ? '#ff003c' : cat.icon.props.className.includes('green') ? '#00ff41' : '#00a2ff' } as any}
                                  />
                               </div>
                            </div>
                          ))}
                       </div>
                    </div>
                  </ScaleIn>
                ))}
             </div>
          </div>
        </section>

        {/* FOOTER */}
        <footer id="comms" className="py-48 bg-black relative border-t-8 border-zinc-900 overflow-hidden group/footer">
           <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(16,185,129,0.05)_0%,transparent_75%)] pointer-events-none" />
           <div className="container mx-auto px-6 relative z-10 text-center">
              <FadeIn>
                 <Clock size={64} className="text-emerald-500 animate-pulse mb-16 mx-auto" />
                 <h2 className="text-7xl md:text-[14rem] font-grotesk font-black uppercase tracking-tighter mb-20 text-white leading-none">
                   Establish <span className="text-emerald-500 group-hover/footer:hero-glitch transition-all duration-700">Link</span>
                 </h2>
                 <p className="text-zinc-600 text-3xl md:text-5xl font-grotesk font-light max-w-6xl mx-auto leading-relaxed italic border-l-8 border-emerald-500/10 pl-16 text-left mb-32">
                    "The infinite buzz of data is only meaningful when filtered through intelligence. Initiate a secure handshake."
                 </p>
              </FadeIn>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-12 mb-32">
                 {[
                   { label: 'SECURE_CHANNEL', value: PERSONAL_INFO.email, icon: <Mail size={40} />, color: 'text-blue-500', href: `mailto:${PERSONAL_INFO.email}` },
                   { label: 'SOCIAL_RELAY', value: 'Neural.auth', icon: <Linkedin size={40} />, color: 'text-red-600', href: PERSONAL_INFO.linkedin },
                   { label: 'GLOBAL_NODE', value: PERSONAL_INFO.location, icon: <Globe size={40} />, color: 'text-emerald-500', href: null }
                 ].map((item, idx) => (
                   <ScaleIn key={idx} className="bg-zinc-950 border-2 border-zinc-900 p-16 rounded-sm text-center flex flex-col items-center group/card hover:bg-black hover:border-emerald-500 transition-all duration-700 shadow-2xl">
                      <motion.div whileHover={{ scale: 1.2, rotate: 10 }} className={`w-24 h-24 bg-black border-2 border-zinc-900 rounded-full flex items-center justify-center mb-12 group-hover/card:${item.color} group-hover/card:border-current shadow-xl transition-all duration-700`}>
                        {item.icon}
                      </motion.div>
                      <p className="text-[11px] text-zinc-700 font-black mono mb-6 tracking-[0.5em] uppercase">{item.label}</p>
                      {item.href ? (
                        <a href={item.href} target="_blank" className="text-2xl md:text-3xl font-black text-white hover:text-emerald-500 transition-colors mono truncate w-full tracking-tighter">{item.value}</a>
                      ) : (
                        <p className="text-2xl md:text-3xl font-black text-white mono tracking-tighter">{item.value}</p>
                      )}
                   </ScaleIn>
                 ))}
              </div>

              <div className="pt-24 border-t-2 border-zinc-900 flex flex-col md:flex-row justify-between items-center gap-16 mono text-[12px] font-black uppercase tracking-[1em] text-zinc-800">
                 <div className="flex gap-12">
                   <span className="hover:text-red-500 transition-colors cursor-crosshair">SHA_512_SECURE</span>
                   <span className="hover:text-blue-500 transition-colors cursor-crosshair">NODE_ACTIVE</span>
                 </div>
                 <p>© 2025 JINESH CHUDASAMA // REV_4.2.0</p>
                 <div className="flex items-center gap-6">
                    <div className="w-3 h-3 rounded-full bg-emerald-500 shadow-[0_0_15px_#10b981] animate-pulse" />
                    <span className="text-emerald-950 tracking-[0.2em]">GRID_CONNECTED</span>
                 </div>
              </div>
           </div>
        </footer>
      </main>
    </div>
  );
};

const SectionHeading: React.FC<{ title: string; subtitle: string; accent: string }> = ({ title, subtitle, accent }) => (
  <div className="mb-24">
    <div className="flex items-center gap-10 mb-10">
      <div className="w-24 h-[6px]" style={{ backgroundColor: accent, boxShadow: `0 0 30px ${accent}` }} />
      <span className="mono text-[14px] font-black uppercase tracking-[1em]" style={{ color: accent }}>{subtitle}</span>
    </div>
    <h3 className="text-6xl md:text-9xl font-grotesk font-black uppercase tracking-tight leading-none text-white">{title}</h3>
  </div>
);

export default App;
